import { resolve } from 'node:path'

/**
 * Regenerates the typed client from the contract the API publishes.
 *
 * `infra/contracts/openapi.json` is generated by the API's own `bun run contracts` and **committed**
 * — it is the artefact other repositories read, and the only place the document lives. This turns it
 * into `src/api/schema.d.ts`, which is **not** committed: in one repository the source of that file
 * is always on disk, so a second copy in git could only ever be a copy that goes stale.
 *
 *     bun run api:types
 */
// The app being built: run from the package directory.
const ROOT = process.cwd()
const CONTRACT = resolve(ROOT, '../../infra/contracts/openapi.json')

if (!(await Bun.file(CONTRACT).exists())) {
  console.error(`  contract: ${CONTRACT} is missing — run \`bun run contracts\` at the repository root`)
  process.exit(1)
}

const generated = Bun.spawnSync(['bunx', 'openapi-typescript', CONTRACT, '-o', 'src/api/schema.d.ts'], {
  cwd: ROOT,
  stderr: 'pipe'
})

if (generated.exitCode !== 0) {
  console.error(generated.stderr.toString())
  process.exit(1)
}

console.error('  contract: src/api/schema.d.ts regenerated from infra/contracts/openapi.json')
